    if (!reviewRow) {
      throw new TRPCError({
        code: "NOT_FOUND",
        message: `Code review ${input.review_id} not found`
      });
    }
    const [authorTask] = await db2.select().from(tasks).where(and(eq(tasks.taskId, reviewRow.prTaskId), eq(tasks.tenantId, ctx.tenantId))).limit(1);
