// ../orchestrator/src/orchestration/persona-lookup.ts
async function resolvePersona(db2, loader, personaIdOrSlug) {
  try {
    const p2 = await loader.get(personaIdOrSlug);
    return p2;
  } catch {
  }
  const rows = await db2.select().from(personas).where(eq(personas.slug, personaIdOrSlug)).limit(1);
  const row = rows[0];
  if (!row) {
    throw new Error(
      `NOT_FOUND_PERSONA: no persona with id-or-slug '${personaIdOrSlug}'`
    );
  }
  return loader.get(row.personaId);
}

